  i = 0
  while i < w
    floorclip[i] = viewheight[0]
    ceilingclip[i] = -1
    i += 1
  end
  state[i_lastvisplane] = 0
  state[i_lastopening] = 0
  state[i_floorplane] = -1
  state[i_ceilingplane] = -1
