def dc_rv_clip_value(openings, viewheight, kind, base, x)
  return viewheight[0] if kind == RL_CLIP_SCREENHEIGHT
  return -1 if kind == RL_CLIP_NEGONE
  openings[base + x]
end

def dc_rv_cp_clear_plane_top(pl_top, plw, plempty, i)
  w = plw[0]
  b = i * w
  x = 0
  while x < w
    pl_top[b + x] = plempty[0]
    x += 1
  end
  0
end

def dc_rv_crunch(state, ss_first, ss_last, i_newend, start, nx)
  return 0 if nx == start
  s = start
  n = nx
  while n != state[i_newend]
    n += 1
    s += 1
    ss_first[s] = ss_first[n]
    ss_last[s] = ss_last[n]
  end
  state[i_newend] = s + 1
  0
end

def dc_rv_draw_column(scr, n_scr, cmap, n_cmap, atlas, n_atlas, wad, n_wad, zonewin, n_zonewin,
                   state, i_res, i_base, x, yl, yh, iscale, texmid, colormap_row,
                   centery, sw, vwx, vwy)
  count = yh - yl
  return 0 if count < 0
  sel = state[i_res]
  return -1 if sel != RES_ATLAS && sel != RES_WAD && sel != RES_ZONE
  base = state[i_base]
  cm = colormap_row * 256
  fracstep = iscale
  frac = core_w32_add(texmid, core_w32_mul(core_w32_sub(yl, centery), fracstep))
  o = (yl + vwy) * sw + x + vwx
  i = 0
  while i <= count
    k = base + ((frac >> 16) & 127)
    b = 0
    if sel == RES_ATLAS
      b = atlas[k]
    elsif sel == RES_WAD
      b = wad[k]
    else
      b = zonewin[k]
    end
    scr[o] = cmap[cm + b]
    o += sw
    frac = core_w32_add(frac, fracstep)
    i += 1
  end
  1
end

def dc_rv_draw_plane(state, pl_minx, pl_maxx, pl_picnum, pl_height, pl_lightlevel, pl_top, pl_bottom,
                  spanstart, cachedheight, cacheddistance, cachedxstep, cachedystep, yslope, distscale,
                  xtoviewangle, finesine, zlight, flattranslation, span, sc_kind, sc_idx, cap_span, cap_sched,
                  plw, plempty, skyflatnum,
                  i_viewz, i_extralight, i_planeheight, i_planezlight, i_curpicnum,
                  i_basexscale, i_baseyscale, i_viewangle, i_viewx, i_viewy, i_nspan, i_nsched, pl, jobmode, scr, cmap, flat, sw, viewwindowx, viewwindowy)
  minx = pl_minx[pl]
  maxx = pl_maxx[pl]
  return 0 if minx > maxx
  # the original sets curpicnum before it tests for the sky
  picnum = pl_picnum[pl]
  state[i_curpicnum] = picnum
  return 1 if picnum == skyflatnum[0]
  ph = pl_height[pl] - state[i_viewz]
  state[i_planeheight] = ph < 0 ? -ph : ph
  light = (pl_lightlevel[pl] >> PL_LIGHTSEGSHIFT) + state[i_extralight]
  light = PL_LIGHTLEVELS - 1 if light >= PL_LIGHTLEVELS
  light = 0 if light < 0
  state[i_planezlight] = light * PL_MAXLIGHTZ
  b = pl * plw[0] + 1
  pl_top[b + maxx + 1] = plempty[0]
  pl_top[b + minx - 1] = plempty[0]
  stop = maxx + 1
  x = minx
  while x <= stop
    dc_rv_make_spans(state, spanstart, cachedheight, cacheddistance, cachedxstep, cachedystep, yslope, distscale,
                  xtoviewangle, finesine, zlight, flattranslation, span, sc_kind, sc_idx, cap_span, cap_sched,
                  i_planeheight, i_basexscale, i_baseyscale, i_viewangle, i_viewx, i_viewy,
                  i_planezlight, i_curpicnum, i_nspan, i_nsched,
                  x, pl_top[b + x - 1], pl_bottom[b + x - 1], pl_top[b + x], pl_bottom[b + x], jobmode, scr, cmap, flat, sw, viewwindowx, viewwindowy)
    x += 1
  end
  0
end

