      state[i_dc_yl] = yl
      state[i_dc_yh] = yh
      state[i_dc_iscale] = pspriteiscale[0]
      state[i_dc_texturemid] = skytexturemid[0]
      state[i_dc_colormap] = 0
      c = (angle & tex_widthmask[tex]) << 7
      state[i_dc_srcofs] = c
      state[i_dc_srcbase] = tex_atlas_base[tex] + c
      if jobmode[0] == 0
        # job mode 0, Renderer#draw_column's direct path: the column drawn here
        state[i_dc_srcres] = RES_ATLAS
        dc_rv_draw_column(scr, 0, cmap, 0, atlas, 0, wad, 0, zonewin, 0, state, i_dc_srcres, i_dc_srcbase,
                       x, yl, yh, pspriteiscale[0], skytexturemid[0], 0, centery[0], sw[0], viewwindowx[0],
                       viewwindowy[0])
      else
        # `emit_column`'s phase-0/1 branch: `push_wall`, written out
        i = state[i_nwall]
        if i >= cap_wall[0]
          core_fail(:capacity)
        end
        wb = i * PL_WC_NF
        wall[wb] = x
        wall[wb + 1] = yl
        wall[wb + 2] = yh
        wall[wb + 3] = pspriteiscale[0]
        wall[wb + 4] = skytexturemid[0]
        wall[wb + 5] = state[i_dc_srcbase]
        wall[wb + 6] = 0
        state[i_nwall] = i + 1
        sc = state[i_nsched]
        if sc >= cap_sched[0]
          core_fail(:capacity)
        end
        sc_kind[sc] = PL_KIND_WALL
        sc_idx[sc] = i
        state[i_nsched] = sc + 1
      end
    end
    x += 1
  end
  0
end

def dc_rv_exec_masked(scr, cmap, wad, zonebuf, fuzzoffset, masked, i, width, centery, vwx, vwy)
  b = i * EX_MC_NF
  yl = masked[b + 1]
  yh = masked[b + 2]
  count = yh - yl
  return 0 if count < 0
  o = (yl + vwy) * width + masked[b] + vwx
  fz = masked[b + 8]
  if fz >= 0
    fp = fz
    k = 0
    while k <= count
      scr[o] = cmap[EX_FUZZ_CMAP * 256 + scr[o + fuzzoffset[fp] * width]]
      fp += 1
      fp = 0 if fp == EX_FUZZ_N
      o += width
      k += 1
    end
    return 1
  end
  sel = masked[b + 5]
  ofs = masked[b + 6]
  cm = masked[b + 7] * 256
  fracstep = masked[b + 3]
  frac = core_w32_add(masked[b + 4], core_w32_mul(core_w32_sub(yl, centery), fracstep))
  k = 0
  while k <= count
    t = ofs + ((frac >> 16) & 127)
    src = 0
    if sel == RES_ZONE
      src = zonebuf[t]
    else
      src = wad[t]
    end
    scr[o] = cmap[cm + src]
    o += width
    frac = core_w32_add(frac, fracstep)
    k += 1
  end
  0
end

def dc_rv_exec_run(scr, cmap, atlas, flat, wad, zonebuf, fuzzoffset, wall, span, masked,
                sc_kind, sc_idx, nsched, width, centery, vwx, vwy)
  fuzz = 0
  i = 0
  while i < nsched
    kind = sc_kind[i]
    j = sc_idx[i]
    if kind == EX_KIND_WALL
      dc_rv_exec_wall(scr, cmap, atlas, wall, j, width, centery, vwx, vwy)
    elsif kind == EX_KIND_SPAN
      dc_rv_exec_span(scr, cmap, flat, span, j, width, vwx, vwy)
    else
      fuzz += dc_rv_exec_masked(scr, cmap, wad, zonebuf, fuzzoffset, masked, j, width, centery, vwx, vwy)
    end
    i += 1
  end
  fuzz
end

def dc_rv_exec_span(scr, cmap, flat, span, i, width, vwx, vwy)
  b = i * EX_SP_NF
  x1 = span[b + 1]
  count = span[b + 2] - x1
  return 0 if count < 0
  ofs = span[b + 5]
  cm = span[b + 6] * 256
  o = (span[b] + vwy) * width + x1 + vwx
  position = span[b + 3]
  step = span[b + 4]
  k = 0
  while k <= count
    spot = core_u32_shr(position, 26) | ((position >> 4) & 0x0fc0)
    scr[o] = cmap[cm + flat[ofs + spot]]
    o += 1
    position = core_w32_add(position, step)
    k += 1
  end
  0
end

def dc_rv_exec_wall(scr, cmap, atlas, wall, i, width, centery, vwx, vwy)
  b = i * EX_WC_NF
  yl = wall[b + 1]
  yh = wall[b + 2]
  count = yh - yl
  return 0 if count < 0
  ofs = wall[b + 5]
  cm = wall[b + 6] * 256
  fracstep = wall[b + 3]
  frac = core_w32_add(wall[b + 4], core_w32_mul(core_w32_sub(yl, centery), fracstep))
  o = (yl + vwy) * width + wall[b] + vwx
  k = 0
  while k <= count
    scr[o] = cmap[cm + atlas[ofs + ((frac >> 16) & 127)]]
    o += width
    frac = core_w32_add(frac, fracstep)
    k += 1
  end
  0
end

def dc_rv_find_plane(state, pl_height, pl_picnum, pl_lightlevel, pl_minx, pl_maxx, pl_top,
                  skyflatnum, sw, plw, plempty, i_lastvisplane, height, picnum, lightlevel)
  if picnum == skyflatnum[0]
    height = 0
    lightlevel = 0
  end
  i = 0
  n = state[i_lastvisplane]
  while i < n
    return i if height == pl_height[i] && picnum == pl_picnum[i] && lightlevel == pl_lightlevel[i]
    i += 1
  end
  if n == RL_MAXVISPLANES
    core_fail(:capacity)
  end
  state[i_lastvisplane] = n + 1
  pl_height[n] = height
  pl_picnum[n] = picnum
  pl_lightlevel[n] = lightlevel
  pl_minx[n] = sw[0]
  pl_maxx[n] = -1
  dc_rv_fp_clear_plane_top(pl_top, plw, plempty, n)
  n
end

def dc_rv_fp_clear_plane_top(pl_top, plw, plempty, i)
  w = plw[0]
  b = i * w
  x = 0
  while x < w
    pl_top[b + x] = plempty[0]
    x += 1
  end
  0
end

def dc_rv_jobs_reset(state, zero_slots, n_zero_slots, i_fuzz_suffix)
  k = 0
  while k < n_zero_slots
    state[zero_slots[k]] = 0
    k += 1
  end
  state[i_fuzz_suffix] = 1
  0
end

def dc_rv_light_index(resscale, scale)
  index = (scale >> RL_LIGHTSCALESHIFT) / resscale[0]
  index >= RL_MAXLIGHTSCALE ? RL_MAXLIGHTSCALE - 1 : index
end

def dc_rv_make_spans(state, spanstart, cachedheight, cacheddistance, cachedxstep, cachedystep, yslope, distscale,
                  xtoviewangle, finesine, zlight, flattranslation, span, sc_kind, sc_idx, cap_span, cap_sched,
                  i_planeheight, i_basexscale, i_baseyscale, i_viewangle, i_viewx, i_viewy,
                  i_planezlight, i_curpicnum, i_nspan, i_nsched, x, t1, b1, t2, b2, jobmode, scr, cmap, flat, sw, viewwindowx, viewwindowy)
  a1 = t1
  c1 = b1
  a2 = t2
  c2 = b2
  while a1 < a2 && a1 <= c1
    dc_rv_plane_span(state, cachedheight, cacheddistance, cachedxstep, cachedystep, yslope, distscale,
                  xtoviewangle, finesine, zlight, flattranslation, span, sc_kind, sc_idx, cap_span, cap_sched,
                  i_planeheight, i_basexscale, i_baseyscale, i_viewangle, i_viewx, i_viewy,
                  i_planezlight, i_curpicnum, i_nspan, i_nsched, a1, spanstart[a1], x - 1, jobmode, scr, cmap, flat, sw, viewwindowx, viewwindowy)
    a1 += 1
  end
  while c1 > c2 && c1 >= a1
    dc_rv_plane_span(state, cachedheight, cacheddistance, cachedxstep, cachedystep, yslope, distscale,
                  xtoviewangle, finesine, zlight, flattranslation, span, sc_kind, sc_idx, cap_span, cap_sched,
                  i_planeheight, i_basexscale, i_baseyscale, i_viewangle, i_viewx, i_viewy,
                  i_planezlight, i_curpicnum, i_nspan, i_nsched, c1, spanstart[c1], x - 1, jobmode, scr, cmap, flat, sw, viewwindowx, viewwindowy)
    c1 -= 1
  end
  while a2 < a1 && a2 <= c2
    spanstart[a2] = x
    a2 += 1
  end
  while c2 > c1 && c2 >= a2
    spanstart[c2] = x
    c2 -= 1
  end
  0
end

def dc_rv_mark_phase1(state, i_nwall, i_wall_phase0_n)
  state[i_wall_phase0_n] = state[i_nwall]
  0
end

def dc_rv_mark_phase3(state, i_nmasked, i_masked_phase2_n)
  state[i_masked_phase2_n] = state[i_nmasked]
  0
end

def dc_rv_plane_span(state, cachedheight, cacheddistance, cachedxstep, cachedystep, yslope, distscale,
                  xtoviewangle, finesine, zlight, flattranslation, span, sc_kind, sc_idx, cap_span, cap_sched,
                  i_planeheight, i_basexscale, i_baseyscale, i_viewangle, i_viewx, i_viewy,
                  i_planezlight, i_curpicnum, i_nspan, i_nsched, y, x1, x2, jobmode, scr, cmap, flat, sw, viewwindowx, viewwindowy)
  ph = state[i_planeheight]
  distance = 0
  xstep = 0
  ystep = 0
  if ph != cachedheight[y]
    cachedheight[y] = ph
    distance = core_fixed_mul(ph, yslope[y])
    cacheddistance[y] = distance
    xstep = core_fixed_mul(distance, state[i_basexscale])
    ystep = core_fixed_mul(distance, state[i_baseyscale])
    cachedxstep[y] = xstep
    cachedystep[y] = ystep
  else
    distance = cacheddistance[y]
    xstep = cachedxstep[y]
    ystep = cachedystep[y]
  end
  length = core_fixed_mul(distance, distscale[x1])
  angle = core_u32_shr(core_w32_add(state[i_viewangle], xtoviewangle[x1]), PS_ANGLETOFINESHIFT)
  c = finesine[angle + 2048]
  s = finesine[angle]
  xfrac = core_w32_add(state[i_viewx], core_fixed_mul(c, length))
  yfrac = core_w32_sub(core_w32_neg(state[i_viewy]), core_fixed_mul(s, length))
  index = distance >> PS_LIGHTZSHIFT
  index = PS_MAXLIGHTZ - 1 if index >= PS_MAXLIGHTZ
  cmrow = zlight[state[i_planezlight] + index]
  # the packed span source: x in the high 16 bits, y in the low 16, bits 6..21
  # of each (C: ((xfrac << 10) & 0xffff0000) | ((yfrac >> 6) & 0xffff)), the
  # high half placed by a word multiply (decision 0022)
  position = core_w32_mul((xfrac >> 6) & 0xffff, 65536) | ((yfrac >> 6) & 0xffff)
  step = core_w32_mul((xstep >> 6) & 0xffff, 65536) | ((ystep >> 6) & 0xffff)
  if jobmode[0] == 0
    # job mode 0, Renderer#draw_span's direct path: the span drawn here, from
    # the flat atlas, by the executor's exec_span's own pixel loop
    fbase = flattranslation[state[i_curpicnum]] * PS_FLAT_BYTES
    cm = cmrow * 256
    o = (y + viewwindowy[0]) * sw[0] + x1 + viewwindowx[0]
    count = x2 - x1
    k = 0
    while k <= count
      spot = core_u32_shr(position, 26) | ((position >> 4) & 0x0fc0)
      scr[o] = cmap[cm + flat[fbase + spot]]
      o += 1
      position = core_w32_add(position, step)
      k += 1
    end
    return 0
  end
  # `push_span`, written out: the record, then the schedule entry
  i = state[i_nspan]
  if i >= cap_span[0]
    core_fail(:capacity)
  end
  b = i * PS_SP_NF
  span[b] = y
  span[b + 1] = x1
  span[b + 2] = x2
  span[b + 3] = position
  span[b + 4] = step
  span[b + 5] = flattranslation[state[i_curpicnum]] * PS_FLAT_BYTES
  span[b + 6] = cmrow
  state[i_nspan] = i + 1
  sc = state[i_nsched]
  if sc >= cap_sched[0]
    core_fail(:capacity)
  end
  sc_kind[sc] = PS_KIND_SPAN
  sc_idx[sc] = i
  state[i_nsched] = sc + 1
  0
end

def dc_rv_point_on_seg_side(vertex_x, vertex_y, seg_v1, seg_v2, x, y, seg)
  lx = vertex_x[seg_v1[seg]]
  ly = vertex_y[seg_v1[seg]]
  ldx = core_w32_sub(vertex_x[seg_v2[seg]], lx)
  ldy = core_w32_sub(vertex_y[seg_v2[seg]], ly)
  if ldx == 0
    return x <= lx ? (ldy > 0 ? 1 : 0) : (ldy < 0 ? 1 : 0)
  end
  if ldy == 0
    return y <= ly ? (ldx < 0 ? 1 : 0) : (ldx > 0 ? 1 : 0)
  end
  dx = core_w32_sub(x, lx)
  dy = core_w32_sub(y, ly)
  neg = 0
  neg += 1 if ldy < 0
  neg += 1 if ldx < 0
  neg += 1 if dx < 0
  neg += 1 if dy < 0
  if neg % 2 == 1
    # the original compares two signs as booleans; the checker proves integer
    # comparisons, so each sign is a 0 or a 1 first
    sy = ldy < 0 ? 1 : 0
    sx = dx < 0 ? 1 : 0
    return sy != sx ? 1 : 0
  end
  left = core_fixed_mul((ldy >> 16), dx)
  right = core_fixed_mul(dy, (ldx >> 16))
  right < left ? 0 : 1
end

def dc_rv_point_to_angle(state, tantoangle, i_viewx, i_viewy, px, py)
  x = core_w32_sub(px, state[i_viewx])
  y = core_w32_sub(py, state[i_viewy])
  return 0 if x == 0 && y == 0
  if x >= 0
    if y >= 0
      return tantoangle[dc_rv_slope_div(y, x)] if x > y
      return core_w32_sub(core_w32_sub(RL_ANG90, 1), tantoangle[dc_rv_slope_div(x, y)])
    end
    y = core_w32_neg(y)
    return core_w32_neg(tantoangle[dc_rv_slope_div(y, x)]) if x > y
    return core_w32_add(RL_ANG270, tantoangle[dc_rv_slope_div(x, y)])
  end
  x = core_w32_neg(x)
  if y >= 0
    return core_w32_sub(core_w32_sub(RL_ANG180, 1), tantoangle[dc_rv_slope_div(y, x)]) if x > y
    return core_w32_add(RL_ANG90, tantoangle[dc_rv_slope_div(x, y)])
  end
  y = core_w32_neg(y)
  return core_w32_add(RL_ANG180, tantoangle[dc_rv_slope_div(y, x)]) if x > y
  core_w32_sub(core_w32_sub(RL_ANG270, 1), tantoangle[dc_rv_slope_div(x, y)])
end

def dc_rv_point_to_dist(state, tantoangle, finesine, i_viewx, i_viewy, px, py)
  dx = (core_w32_sub(px, state[i_viewx])).abs
  dy = (core_w32_sub(py, state[i_viewy])).abs
  if dy > dx
    t = dx
    dx = dy
    dy = t
  end
  frac = dx != 0 ? core_fixed_div(dy, dx) : 0
  angle = core_u32_shr(core_w32_add(tantoangle[frac >> 5], RL_ANG90), RL_ANGLETOFINESHIFT)
  core_fixed_div(dx, finesine[angle])
end

def dc_rv_project_sprite(state, mobj_x, mobj_y, mobj_z, mobj_angle, mobj_frame, mobj_sprite, mobj_flags,
                      numframes, rotate, framebase, sprlump, sprflip, spriteoffset, spritewidth,
                      spritetopoffset, tantoangle, projection, centerxfrac, viewwidth, scalelight, resscale,
                      vs_mobjflags, vs_scale, vs_gx, vs_gy, vs_gz, vs_gzt, vs_texturemid, vs_x1, vs_x2,
                      vs_startfrac, vs_xiscale, vs_patch, vs_cmap,
                      i_viewx, i_viewy, i_viewz, i_viewcos, i_viewsin, i_spritelights, i_vis_n, thing)
  tr_x = core_w32_sub(mobj_x[thing], state[i_viewx])
  tr_y = core_w32_sub(mobj_y[thing], state[i_viewy])
  gxt = core_fixed_mul(tr_x, state[i_viewcos])
  gyt = core_fixed_mul(tr_y, state[i_viewsin])
  gyt = core_w32_neg(gyt)
  tz = core_w32_sub(gxt, gyt)
  return 0 if tz < RL_MINZ
  xscale = core_fixed_div(projection[0], tz)
  gxt = core_fixed_mul(tr_x, state[i_viewsin])
  gxt = core_w32_neg(gxt)
  gyt = core_fixed_mul(tr_y, state[i_viewcos])
  tx = core_w32_neg(core_w32_add(gyt, gxt))
  atx = tx < 0 ? -tx : tx
  return 0 if atx > (core_w32_mul(tz, 4))
  spr = mobj_sprite[thing]
  frame = mobj_frame[thing] & RL_FF_FRAMEMASK
  if frame >= numframes[spr]
    core_fail(:capacity)
  end
  fb = framebase[spr] + frame
  rot = 0
  if rotate[fb] != 0
    ang = dc_rv_ps_point_to_angle(state, tantoangle, i_viewx, i_viewy, mobj_x[thing], mobj_y[thing])
    # (ANG45 / 2) * 9 is 0x90000000, here its signed pattern
    rot = core_u32_shr(core_w32_add(core_w32_sub(ang, mobj_angle[thing]), -1879048192), 29)
  end
  lump = sprlump[fb * 8 + rot]
  flip = sprflip[fb * 8 + rot]
  tx = core_w32_sub(tx, spriteoffset[lump])
  x1 = (core_w32_add(centerxfrac[0], core_fixed_mul(tx, xscale))) >> 16
  return 0 if x1 > viewwidth[0]
  tx = core_w32_add(tx, spritewidth[lump])
  x2 = (core_w32_add(centerxfrac[0], core_fixed_mul(tx, xscale)))
  x2 = (x2 >> 16) - 1
  return 0 if x2 < 0
  v = state[i_vis_n]
  if v == RL_MAXVISSPRITES
    core_fail(:capacity)
  end
  state[i_vis_n] = v + 1
  flags = mobj_flags[thing]
  vs_mobjflags[v] = flags
  vs_scale[v] = xscale
  vs_gx[v] = mobj_x[thing]
  vs_gy[v] = mobj_y[thing]
  vs_gz[v] = mobj_z[thing]
  gzt = core_w32_add(mobj_z[thing], spritetopoffset[lump])
  vs_gzt[v] = gzt
  vs_texturemid[v] = core_w32_sub(gzt, state[i_viewz])
  vs_x1[v] = x1 < 0 ? 0 : x1
  vs_x2[v] = x2 >= viewwidth[0] ? viewwidth[0] - 1 : x2
  iscale = core_fixed_div(RL_FRACUNIT, xscale)
  if flip != 0
    vs_startfrac[v] = spritewidth[lump] - 1
    vs_xiscale[v] = core_w32_neg(iscale)
  else
    vs_startfrac[v] = 0
    vs_xiscale[v] = iscale
  end
  if vs_x1[v] > x1
    d = core_w32_mul(vs_xiscale[v], core_w32_sub(vs_x1[v], x1))
    vs_startfrac[v] = core_w32_add(vs_startfrac[v], d)
  end
  vs_patch[v] = lump
  if (flags & RL_MF_TRANSLATION) != 0
    core_fail(:capacity)
  end
  if (mobj_frame[thing] & RL_FF_FULLBRIGHT) != 0
    vs_cmap[v] = 0
  else
    vs_cmap[v] = scalelight[state[i_spritelights] + dc_rv_ps_light_index(resscale, xscale)]
  end
  0
end

def dc_rv_ps_light_index(resscale, scale)
  index = (scale >> RL_LIGHTSCALESHIFT) / resscale[0]
  index >= RL_MAXLIGHTSCALE ? RL_MAXLIGHTSCALE - 1 : index
end

def dc_rv_ps_point_to_angle(state, tantoangle, i_viewx, i_viewy, px, py)
  x = core_w32_sub(px, state[i_viewx])
  y = core_w32_sub(py, state[i_viewy])
  return 0 if x == 0 && y == 0
  if x >= 0
    if y >= 0
      return tantoangle[dc_rv_ps_slope_div(y, x)] if x > y
      return core_w32_sub(core_w32_sub(RL_ANG90, 1), tantoangle[dc_rv_ps_slope_div(x, y)])
    end
    y = core_w32_neg(y)
    return core_w32_neg(tantoangle[dc_rv_ps_slope_div(y, x)]) if x > y
    return core_w32_add(RL_ANG270, tantoangle[dc_rv_ps_slope_div(x, y)])
  end
  x = core_w32_neg(x)
  if y >= 0
    return core_w32_sub(core_w32_sub(RL_ANG180, 1), tantoangle[dc_rv_ps_slope_div(y, x)]) if x > y
    return core_w32_add(RL_ANG90, tantoangle[dc_rv_ps_slope_div(x, y)])
  end
  y = core_w32_neg(y)
  return core_w32_add(RL_ANG180, tantoangle[dc_rv_ps_slope_div(y, x)]) if x > y
  core_w32_sub(core_w32_sub(RL_ANG270, 1), tantoangle[dc_rv_ps_slope_div(x, y)])
end

def dc_rv_ps_slope_div(num, den)
  # C's unsigned arguments (decision 0022): den compared and shifted as a word,
  # and (num << 3) / (den >> 8) an unsigned quotient. With u = num << 3,
  # h = u >>> 1 and dd >= 2, u / dd = 2 (h / dd) + (2 (h % dd) + (u & 1)) / dd,
  # no term past i32.
  return 2048 if core_u32_lt(den, 512)
  u = core_w32_mul(num, 8)
  dd = core_u32_shr(den, 8)
  h = core_u32_shr(u, 1)
  ans = (h / dd) * 2 + ((h % dd) * 2 + (u & 1)) / dd
  ans <= 2048 ? ans : 2048
end

def dc_rv_push_masked(state, masked, sc_kind, sc_idx, cap_masked, cap_sched, i_nmasked, i_nsched,
                   x, yl, yh, iscale, texmid, srcres, srcofs, cmap, fuzz)
  i = state[i_nmasked]
  if i >= cap_masked[0]
    core_fail(:capacity)
  end
  b = i * JB_MC_NF
  masked[b] = x
  masked[b + 1] = yl
  masked[b + 2] = yh
  masked[b + 3] = iscale
  masked[b + 4] = texmid
  masked[b + 5] = srcres
  masked[b + 6] = srcofs
  masked[b + 7] = cmap
  masked[b + 8] = fuzz
  state[i_nmasked] = i + 1
  s = state[i_nsched]
  if s >= cap_sched[0]
    core_fail(:capacity)
  end
  sc_kind[s] = JB_KIND_MASKED
  sc_idx[s] = i
  state[i_nsched] = s + 1
  0
end

def dc_rv_push_wall(state, wall, sc_kind, sc_idx, cap_wall, cap_sched, i_nwall, i_nsched,
                 x, yl, yh, iscale, texmid, srcofs, cmap)
  i = state[i_nwall]
  if i >= cap_wall[0]
    core_fail(:capacity)
  end
  b = i * JB_WC_NF
  wall[b] = x
  wall[b + 1] = yl
  wall[b + 2] = yh
  wall[b + 3] = iscale
  wall[b + 4] = texmid
  wall[b + 5] = srcofs
  wall[b + 6] = cmap
  state[i_nwall] = i + 1
  s = state[i_nsched]
  if s >= cap_sched[0]
    core_fail(:capacity)
  end
  sc_kind[s] = JB_KIND_WALL
  sc_idx[s] = i
  state[i_nsched] = s + 1
  0
end

def dc_rv_render_seg_loop(state, ceilingclip, floorclip, pl_top, pl_bottom, openings, xtoviewangle, finetangent, finesine,
                       scalelight, resscale, tex_widthmask, tex_atlas_base, plw, viewheight, jobmode,
                       scr, cmap, atlas, wad, zonewin, centery, sw, viewwindowx, viewwindowy,
                       wall, sc_kind, sc_idx, cap_wall, cap_sched,
                       i_rw_x, i_rw_stopx, i_topfrac, i_bottomfrac, i_topstep, i_bottomstep,
                       i_pixhigh, i_pixlow, i_pixhighstep, i_pixlowstep, i_rw_scale, i_rw_scalestep,
                       i_markceiling, i_markfloor, i_ceilingplane, i_floorplane, i_segtextured,
                       i_rw_centerangle, i_rw_distance, i_rw_offset, i_walllights,
                       i_midtexture, i_toptexture, i_bottomtexture, i_maskedtexture,
                       i_rw_midtexturemid, i_rw_toptexturemid, i_rw_bottomtexturemid, i_maskedtexturecol,
                       i_dc_x, i_dc_yl, i_dc_yh, i_dc_iscale, i_dc_texturemid, i_dc_colormap, i_dc_srcofs,
                       i_dc_srcres, i_dc_srcbase, i_nwall, i_nsched)
  columns = 0
  pw = plw[0]
  cy = centery[0]
  width = sw[0]
  vwx = viewwindowx[0]
  vwy = viewwindowy[0]
  jm = jobmode[0]
  while state[i_rw_x] < state[i_rw_stopx]
    x = state[i_rw_x]

    yl = core_w32_sub(core_w32_add(state[i_topfrac], SL_HEIGHTUNIT), 1)
    yl = yl >> SL_HEIGHTBITS
    cc = ceilingclip[x]
    yl = cc + 1 if yl < cc + 1

    if state[i_markceiling] != 0
      top = ceilingclip[x] + 1
      bottom = yl - 1
      bottom = floorclip[x] - 1 if bottom >= floorclip[x]
      if top <= bottom
        b = state[i_ceilingplane] * pw + 1 + x
        pl_top[b] = top
        pl_bottom[b] = bottom
      end
    end

    yh = state[i_bottomfrac] >> SL_HEIGHTBITS
    fc = floorclip[x]
    yh = fc - 1 if yh >= fc

    if state[i_markfloor] != 0
      top = yh + 1
      bottom = floorclip[x] - 1
      top = ceilingclip[x] + 1 if top <= ceilingclip[x]
      if top <= bottom
        b = state[i_floorplane] * pw + 1 + x
        pl_top[b] = top
        pl_bottom[b] = bottom
      end
    end

    texturecolumn = 0
    if state[i_segtextured] != 0
      angle = core_u32_shr(core_w32_add(state[i_rw_centerangle], xtoviewangle[x]), SL_ANGLETOFINESHIFT)
      # angle is SL_FINETANGENT_COUNT, one past the table, when the sum is
      # exactly ANG180; vanilla reads the next table in memory, finesine[0].
      # As lib/doom/render.rb's render_seg_loop does (see its comment).
      ft = angle == SL_FINETANGENT_COUNT ? finesine[0] : finetangent[angle]
      m = core_fixed_mul(ft, state[i_rw_distance])
      texturecolumn = (core_w32_sub(state[i_rw_offset], m)) >> 16
      index = dc_rv_sl_light_index(resscale, state[i_rw_scale])
      state[i_dc_colormap] = scalelight[state[i_walllights] + index]
      state[i_dc_x] = x
      # unsigned 32-bit division, as `dc_iscale = 0xffffffff / rw_scale`
      state[i_dc_iscale] = dc_rv_sl_umax_div(state[i_rw_scale])
    end

    mid_tex = state[i_midtexture]
    if mid_tex != 0
      state[i_dc_yl] = yl
      state[i_dc_yh] = yh
      state[i_dc_texturemid] = state[i_rw_midtexturemid]
      dc_rv_sl_wall_column(state, tex_widthmask, tex_atlas_base, scr, cmap, atlas, wad, zonewin,
                        wall, sc_kind, sc_idx, cap_wall, cap_sched,
                        i_dc_x, i_dc_yl, i_dc_yh, i_dc_iscale, i_dc_texturemid, i_dc_colormap,
                        i_dc_srcofs, i_dc_srcres, i_dc_srcbase, i_nwall, i_nsched,
                        jm, mid_tex, texturecolumn, cy, width, vwx, vwy)
      columns += 1
      ceilingclip[x] = ((viewheight[0] & SL_M16) ^ SL_SGN16) - SL_SGN16
      floorclip[x] = -1
    else
      top_tex = state[i_toptexture]
      if top_tex != 0
        mid = state[i_pixhigh] >> SL_HEIGHTBITS
        state[i_pixhigh] = core_w32_add(state[i_pixhigh], state[i_pixhighstep])
        mid = floorclip[x] - 1 if mid >= floorclip[x]
        if mid >= yl
          state[i_dc_yl] = yl
          state[i_dc_yh] = mid
          state[i_dc_texturemid] = state[i_rw_toptexturemid]
          dc_rv_sl_wall_column(state, tex_widthmask, tex_atlas_base, scr, cmap, atlas, wad, zonewin,
                            wall, sc_kind, sc_idx, cap_wall, cap_sched,
                            i_dc_x, i_dc_yl, i_dc_yh, i_dc_iscale, i_dc_texturemid, i_dc_colormap,
                            i_dc_srcofs, i_dc_srcres, i_dc_srcbase, i_nwall, i_nsched,
                            jm, top_tex, texturecolumn, cy, width, vwx, vwy)
          columns += 1
          ceilingclip[x] = ((mid & SL_M16) ^ SL_SGN16) - SL_SGN16
        else
          ceilingclip[x] = (((yl - 1) & SL_M16) ^ SL_SGN16) - SL_SGN16
        end
      elsif state[i_markceiling] != 0
        ceilingclip[x] = (((yl - 1) & SL_M16) ^ SL_SGN16) - SL_SGN16
      end

      bottom_tex = state[i_bottomtexture]
      if bottom_tex != 0
        mid = core_w32_sub(core_w32_add(state[i_pixlow], SL_HEIGHTUNIT), 1)
        mid = mid >> SL_HEIGHTBITS
        state[i_pixlow] = core_w32_add(state[i_pixlow], state[i_pixlowstep])
        mid = ceilingclip[x] + 1 if mid <= ceilingclip[x]
        if mid <= yh
          state[i_dc_yl] = mid
          state[i_dc_yh] = yh
          state[i_dc_texturemid] = state[i_rw_bottomtexturemid]
          dc_rv_sl_wall_column(state, tex_widthmask, tex_atlas_base, scr, cmap, atlas, wad, zonewin,
                            wall, sc_kind, sc_idx, cap_wall, cap_sched,
                            i_dc_x, i_dc_yl, i_dc_yh, i_dc_iscale, i_dc_texturemid, i_dc_colormap,
                            i_dc_srcofs, i_dc_srcres, i_dc_srcbase, i_nwall, i_nsched,
                            jm, bottom_tex, texturecolumn, cy, width, vwx, vwy)
          columns += 1
          floorclip[x] = ((mid & SL_M16) ^ SL_SGN16) - SL_SGN16
        else
          floorclip[x] = (((yh + 1) & SL_M16) ^ SL_SGN16) - SL_SGN16
        end
      elsif state[i_markfloor] != 0
        floorclip[x] = (((yh + 1) & SL_M16) ^ SL_SGN16) - SL_SGN16
      end

      if state[i_maskedtexture] != 0
        # `maskedtexturecol` is a short[] in C: 16 bits
        openings[state[i_maskedtexturecol] + x] = ((texturecolumn & SL_M16) ^ SL_SGN16) - SL_SGN16
      end
      # the branch's value, so the no-else `if` above is a statement (the
      # kernel types every conditional that ends a branch)
      0
    end

    state[i_rw_scale] = core_w32_add(state[i_rw_scale], state[i_rw_scalestep])
    state[i_topfrac] = core_w32_add(state[i_topfrac], state[i_topstep])
    state[i_bottomfrac] = core_w32_add(state[i_bottomfrac], state[i_bottomstep])
    state[i_rw_x] = x + 1
  end
  columns
end

def dc_rv_scale_from_global_angle(state, finesine, projection, i_viewangle, i_rw_normalangle, i_rw_distance,
                               visangle)
  anglea = core_w32_add(RL_ANG90, (core_w32_sub(visangle, state[i_viewangle])))
  angleb = core_w32_add(RL_ANG90, (core_w32_sub(visangle, state[i_rw_normalangle])))
  sinea = finesine[core_u32_shr(anglea, RL_ANGLETOFINESHIFT)]
  sineb = finesine[core_u32_shr(angleb, RL_ANGLETOFINESHIFT)]
  num = core_fixed_mul(projection[0], sineb)
  den = core_fixed_mul(state[i_rw_distance], sinea)
  return 64 * RL_FRACUNIT unless den > (num >> 16)
  scale = core_fixed_div(num, den)
  return 64 * RL_FRACUNIT if scale > 64 * RL_FRACUNIT
  return 256 if scale < 256
  scale
end

def dc_rv_sl_draw_column(scr, n_scr, cmap, n_cmap, atlas, n_atlas, wad, n_wad, zonewin, n_zonewin,
                   state, i_res, i_base, x, yl, yh, iscale, texmid, colormap_row,
                   centery, sw, vwx, vwy)
  count = yh - yl
  return 0 if count < 0
  sel = state[i_res]
  return -1 if sel != RES_ATLAS && sel != RES_WAD && sel != RES_ZONE
  base = state[i_base]
  cm = colormap_row * 256
  fracstep = iscale
  frac = core_w32_add(texmid, core_w32_mul(core_w32_sub(yl, centery), fracstep))
  o = (yl + vwy) * sw + x + vwx
  i = 0
  while i <= count
    k = base + ((frac >> 16) & 127)
    b = 0
    if sel == RES_ATLAS
      b = atlas[k]
    elsif sel == RES_WAD
      b = wad[k]
    else
      b = zonewin[k]
    end
    scr[o] = cmap[cm + b]
    o += sw
    frac = core_w32_add(frac, fracstep)
    i += 1
  end
  1
end

def dc_rv_sl_light_index(resscale, scale)
  index = (scale >> RL_LIGHTSCALESHIFT) / resscale[0]
  index >= RL_MAXLIGHTSCALE ? RL_MAXLIGHTSCALE - 1 : index
end

def dc_rv_sl_push_wall(state, wall, sc_kind, sc_idx, cap_wall, cap_sched, i_nwall, i_nsched,
                 x, yl, yh, iscale, texmid, srcofs, cmap)
  i = state[i_nwall]
  if i >= cap_wall[0]
    core_fail(:capacity)
  end
  b = i * JB_WC_NF
  wall[b] = x
  wall[b + 1] = yl
  wall[b + 2] = yh
  wall[b + 3] = iscale
  wall[b + 4] = texmid
  wall[b + 5] = srcofs
  wall[b + 6] = cmap
  state[i_nwall] = i + 1
  s = state[i_nsched]
  if s >= cap_sched[0]
    core_fail(:capacity)
  end
  sc_kind[s] = JB_KIND_WALL
  sc_idx[s] = i
  state[i_nsched] = s + 1
  0
end

def dc_rv_sl_src_texture_column(state, i_res, i_base, atlas_base, widthmask, col)
  state[i_res] = RES_ATLAS
  state[i_base] = atlas_base + ((col & widthmask) << 7)
  0
end

def dc_rv_sl_umax_div(s)
  q = 2147483647 / s
  r = 2147483647 % s
  core_w32_add(core_w32_mul(q, 2), r >= s - 1 - r ? 1 : 0)
end

def dc_rv_sl_wall_column(state, tex_widthmask, tex_atlas_base, scr, cmap, atlas, wad, zonewin,
                      wall, sc_kind, sc_idx, cap_wall, cap_sched,
                      i_dc_x, i_dc_yl, i_dc_yh, i_dc_iscale, i_dc_texturemid, i_dc_colormap,
                      i_dc_srcofs, i_dc_srcres, i_dc_srcbase, i_nwall, i_nsched,
                      jobmode, tex, col, centery, sw, vwx, vwy)
  state[i_dc_srcofs] = (col & tex_widthmask[tex]) << 7
  dc_rv_sl_src_texture_column(state, i_dc_srcres, i_dc_srcbase, tex_atlas_base[tex], tex_widthmask[tex], col)
  if jobmode != 0
    dc_rv_sl_push_wall(state, wall, sc_kind, sc_idx, cap_wall, cap_sched, i_nwall, i_nsched,
                    state[i_dc_x], state[i_dc_yl], state[i_dc_yh], state[i_dc_iscale],
                    state[i_dc_texturemid], state[i_dc_srcbase], state[i_dc_colormap])
  else
    dc_rv_sl_draw_column(scr, 0, cmap, 0, atlas, 0, wad, 0, zonewin, 0,
                      state, i_dc_srcres, i_dc_srcbase, state[i_dc_x], state[i_dc_yl], state[i_dc_yh],
                      state[i_dc_iscale], state[i_dc_texturemid], state[i_dc_colormap],
                      centery, sw, vwx, vwy)
  end
  0
end

def dc_rv_slope_div(num, den)
  # C's unsigned arguments (decision 0022): den compared and shifted as a word,
  # and (num << 3) / (den >> 8) an unsigned quotient. With u = num << 3,
  # h = u >>> 1 and dd >= 2, u / dd = 2 (h / dd) + (2 (h % dd) + (u & 1)) / dd,
  # no term past i32.
  return 2048 if core_u32_lt(den, 512)
  u = core_w32_mul(num, 8)
  dd = core_u32_shr(den, 8)
  h = core_u32_shr(u, 1)
  ans = (h / dd) * 2 + ((h % dd) * 2 + (u & 1)) / dd
  ans <= 2048 ? ans : 2048
end

def dc_rv_sort_vissprites(state, vs_scale, vs_taken, vs_sorted, i_vis_n)
  n = state[i_vis_n]
  i = 0
  while i < n
    vs_taken[i] = 0
    i += 1
  end
  k = 0
  while k < n
    best = -1
    bestscale = 0x7fffffff
    i = 0
    while i < n
      if vs_taken[i] == 0
        best = i if best < 0
        if vs_scale[i] < bestscale
          bestscale = vs_scale[i]
          best = i
        end
      end
      i += 1
    end
    vs_taken[best] = 1
    vs_sorted[k] = best
    k += 1
  end
  0
end

def dc_rv_st_point_in_subsector(num_nodes, node_x, node_y, node_dx, node_dy, node_child0, node_child1, x, y)
  return 0 if num_nodes[0] == 0
  nodenum = num_nodes[0] - 1
  while (nodenum & 0x8000) == 0
    side = dc_rv_st_point_on_side(node_x, node_y, node_dx, node_dy, x, y, nodenum)
    nodenum = side == 0 ? node_child0[nodenum] : node_child1[nodenum]
  end
  nodenum & 0x7fff
end

def dc_rv_st_point_on_side(node_x, node_y, node_dx, node_dy, x, y, n)
  ndx = node_dx[n]
  ndy = node_dy[n]
  if ndx == 0
    if x <= node_x[n]
      return ndy > 0 ? 1 : 0
    end
    return ndy < 0 ? 1 : 0
  end
  if ndy == 0
    if y <= node_y[n]
      return ndx < 0 ? 1 : 0
    end
    return ndx > 0 ? 1 : 0
  end
  dx = core_w32_sub(x, node_x[n])
  dy = core_w32_sub(y, node_y[n])
  neg = 0
  neg += 1 if ndy < 0
  neg += 1 if ndx < 0
  neg += 1 if dx < 0
  neg += 1 if dy < 0
  if (neg & 1) != 0
    a = ndy < 0 ? 1 : 0
    b = dx < 0 ? 1 : 0
    return a != b ? 1 : 0
  end
  left = core_fixed_mul((ndy >> 16), dx)
  right = core_fixed_mul(dy, (ndx >> 16))
  right < left ? 0 : 1
end

def dc_rv_zone_header_byte(lump_size, next_lump, ln, k)
  nx = next_lump[ln]
  return 0 if nx < 0
  if k < 4
    sz = (((lump_size[nx] + 7) >> 3) << 3) + ZONE_HEADER
    (sz >> (k << 3)) & 0xff
  elsif k >= 16 && k < 20
    k == 16 ? ZONE_TAG_CACHE : 0
  elsif k >= 20 && k < 24
    (ZONE_ID >> ((k - 20) << 3)) & 0xff
  else
    0
  end
end

def dc_rv_zone_window_into(wad, lump_pos, lump_size, next_lump, out, lumpnum, off, base)
  ln = lumpnum
  a = off
  i = 0
  while i < 128
    size = lump_size[ln]
    if a < size
      out[base + i] = wad[lump_pos[ln] + a]
      i += 1
      a += 1
    else
      j = a - size
      pad = (((size + 7) >> 3) << 3) - size
      if j < pad + ZONE_HEADER
        b = 0
        if j >= pad
          b = dc_rv_zone_header_byte(lump_size, next_lump, ln, j - pad)
        end
        out[base + i] = b
        i += 1
        a += 1
      else
        nx = next_lump[ln]
        if nx < 0
          out[base + i] = 0
          i += 1
          a += 1
        else
          ln = nx
          a = j - pad - ZONE_HEADER
        end
      end
    end
  end
  0
end

